const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Point of interest: Coastal Sage UCI station, California. Approximate coordinates.
  const point = ee.Geometry.Point([-117.79, 33.65]);

  // Date ranges for comparison.
  const jan2013_start = '2013-01-01';
  const jan2013_end = '2013-01-31';
  const may2013_start = '2013-05-01';
  const may2013_end = '2013-05-31';

  // 2. Data Acquisition & Check
  // The SMAP dataset starts in 2015, so we must use a fallback.
  // ERA5-Land provides modeled soil moisture data and is available for 2013.
  const dataset = ee.ImageCollection('ECMWF/ERA5-LAND/HOURLY')
                      .select('swvl1'); // Volumetric soil water layer 1 (m³/m³)

  const janCollection = dataset.filterDate(jan2013_start, jan2013_end).filterBounds(point);
  const mayCollection = dataset.filterDate(may2013_start, may2013_end).filterBounds(point);

  const janSize = janCollection.size().getInfo();
  const maySize = mayCollection.size().getInfo();

  if (janSize === 0 || maySize === 0) {
    console.log(`Image count January 2013: ${janSize}`);
    console.log(`Image count May 2013: ${maySize}`);
    console.log("Empty collection for one or both periods. Cannot proceed.");
    console.log("C1");
    return;
  }

  // 3. Processing
  // Create a mean composite for each month.
  const janImage = janCollection.mean();
  const mayImage = mayCollection.mean();

  // 4. Calculation
  // Extract the mean soil moisture value at the point.
  // Scale is set to 1000 to match the approximate resolution of the data and avoid timeouts.
  const janMean = janImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 1000,
    maxPixels: 1e9
  }).get('swvl1');

  const mayMean = mayImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 1000,
    maxPixels: 1e9
  }).get('swvl1');

  const janValue = janMean.getInfo();
  const mayValue = mayMean.getInfo();

  // 5. Validation & Final Answer
  console.log(`Image count Jan 2013: ${janSize}`);
  console.log(`Image count May 2013: ${maySize}`);

  if (janValue === null || mayValue === null) {
    console.log("Calculation resulted in null values.");
    console.log("C3");
    return;
  }

  console.log(`January 2013 mean soil moisture (m³/m³): ${janValue.toFixed(4)}`);
  console.log(`May 2013 mean soil moisture (m³/m³): ${mayValue.toFixed(4)}`);

  if (janValue > mayValue) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
